{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE or replace TABLE tekkitake-wh.maplemonk.shipment_status_mapping (SHIPPING_STATUS string(16777216),Mapped_Status string(16777216)); Insert INTO tekkitake-wh.maplemonk.shipment_status_mapping values (\'DELIVERED\',\'Delivered\'),(\'CANCELLED\',\'Cancelled\'),(\'DELIVERED TO ORIGIN\',\'Returned\'),(\'SHIPMENT CREATED\',\'Shipment Created\'),(\'RETURNED\',\'Returned\'),(\'IN TRANSIT\',\'In Transit\'),(\'DELIVERY DELAYED\',\'In Transit\'),(\'DELIVERED TO ORIGIN\',\'RTO\'),(\'CONFIRMED\',\'Open\'),(\'IN_TRANSIT\',\'In Transit\'),(\'RTO DELIVERED\',\'RTO\'),(\'CANCELED\',\'Cancelled\'),(\'RTO IN TRANSIT\',\'RTO\'),(\'REACHED AT DESTINATION HUB\',\'In Transit\'),(\'PICKED UP\',\'In Transit\'),(\'UNDELIVERED-2ND ATTEMPT\',\'In Transit\'),(\'RTO_OFD\',\'RTO\'),(\'OUT FOR DELIVERY\',\'Out for delivery\'),(\'RTO INITIATED\',\'RTO\'),(\'PICKUP EXCEPTION\',\'Pickup Error\'),(\'CANCELLATION REQUESTED\',\'Pickup Error\'),(\'READY TO SHIP\',\'Ready to Ship\'),(\'OUT_FOR_DELIVERY\',\'Out for delivery\'),(\'SHIPPED\',\'In Transit\'),(\'PICKUP RESCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-3RD ATTEMPT\',\'In Transit\'),(\'MISROUTED\',\'Misrouted\'),(\'PICKUP SCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-1ST ATTEMPT\',\'In Transit\'),(\'Not Traceble\',\'Pickup Error\'),(\'UNDELIVERED\',\'In Transit\'),(\'LOST\',\'Lost\'),(\'IN TRANSIT-EN-ROUTE\',\'In Transit\'),(\'Indian Speed Post\',\'Indian Speed Post\'),(\'Exception\',\'Exception\'),(\'Shipment Booked\',\'Pickup Error\'),(\'Assigned\',\'Assigned\'),(\'Pending\',\'Pending\'),(\'PrINT\',\'PrINT\'),(\'IN TRANSIT-AT DESTINATION HUB\',\'In Transit\'),(\'Upcoming\',\'Order Yet To sync\'),(\'RTO-In Transit\',\'RTO\'),(\'PICKUP ERROR\',\'Pickup Error\'),(\'RTO-Out for Delivery\',\'RTO\'),(\'RTO-Delivered\',\'RTO\'),(\'OUT FOR PICKUP\',\'Pickup Error\'),(\'RTO_NDR\',\'RTO\'),(\'RTO-Exception\',\'Exception\'),(\'Delayed\',\'In Transit\'),(\'IN TRANSIT-AT SOURCE HUB\',\'In Transit\'),(\'RTS\',\'Underprocess\'),(\'Manifested\',\'Pickup Error\'),(\'Dispatched\',\'In Transit\'),(\'RTO\',\'RTO\'),(\'Not Picked\',\'Pickup Error\'),(\'DAMAGED\',\'Damaged\'),(\'Closed\',\'Cancelled\'),(\'Open\',\'Open\'),(\'On Hold\',\'On Hold\'),(\'Shipped - Returned to Seller\',\'RTO\'),(\'Shipped - Delivered to Buyer\',\'Delivered\'),(\'Shipped - Picked Up\',\'In Transit\'),(\'Shipped - Rejected by Buyer\',\'RTO\'),(\'Shopify_Processed\',\'Shopify_Processed\'),(\'Ready to dispatch\',\'Ready to Dispatch\'),(\'RTO Undelivered\',\'RTO\'),(\'Shipment Lost\',\'Lost\'),(\'Shipment Error\',\'Shipment Error\'),(\'RTO In-Transit\',\'RTO\'),(\'Dispatch / RTO\',\'RTO\'),(\'Pending Pick-up\',\'Pending\'),(\'Dispatch/Intransit\',\'In Transit\'),(\'Dispatch /Lost and Damange\',\'Lost\'),(\'Dispatch /Undelivered\',\'Undelivered\'),(\'Non serviceable\',\'Non Serviceable\'),(\'Not serviceable\',\'Non Serviceable\'),(\'Dispatch/Delivered\',\'Delivered\'),(\'Refund\',\'Refund\'),(\'F&P\',\'F&P\'),(\'SHIPPED - RETURNING TO SELLER\',\'RTO\'),(\'SHIPPED - LOST IN TRANSIT\',\'Lost\'),(\'SHIPPED - DAMAGED\',\'Damaged\'),(\'SHIPPED - OUT FOR DELIVERY\',\'Out for delivery\'); create table if not exists tekkitake-wh.maplemonk.facility_pincode (facility string,pincode string); CREATE TABLE IF NOT EXISTS tekkitake-wh.MAPLEMONK.TEKKITAKE_UNICOMMERCE_FACT_ITEMS ( order_id STRING, order_Date DATE, reference_code STRING, name STRING, email STRING, city STRING, state STRING, phone STRING, saleorderitemcode STRING, sales_order_item_id STRING, shippingpackagecode STRING, SHIPPINGPACKAGESTATUS STRING, shipping_status STRING, order_status STRING, Courier STRING, Dispatch_Date DATE, Delivered_date DATE, Return_flag INT64, Return_quantity INT64, suborder_quantity INT64, cancelled_quantity INT64, selling_price FLOAT64, shipping_price FLOAT64, tax FLOAT64, discount FLOAT64, shipping_last_update_date DATE, days_in_shipment FLOAT64, awb STRING, marketplace STRING, payment_method STRING, PAYMENT_MODE STRING, PRODUCT_ID STRING, SKU STRING, SKU_CODE STRING, currency STRING, NEW_CUSTOMER_FLAG STRING, product_name STRING, mapped_product_name STRING, product_name_final STRING, mapped_category STRING, product_category STRING, mapped_sub_category STRING, product_sub_category STRING, warehouse_name STRING, pincode STRING, commonsku STRING ); create or replace table tekkitake-wh.maplemonk.tekkitake_sales_consolidated_intermediate as SELECT NULL AS customer_id ,UPPER(marketplace) AS shop_name ,UPPER(marketplace) AS marketplace ,UPPER(marketplace) AS CHANNEL ,UPPER(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,phone AS PHONE ,name AS NAME ,email AS EMAIL ,cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,SKU ,b.PRODUCT_ID ,PRODUCT_NAME AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS city ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS order_status ,CAST(ORDER_DATE AS DATE) AS Order_Date ,CAST(ORDER_DATE AS datetime) ORDER_TIME ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) AS gross_sales_before_tax ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_ORDER_STATUS ,UPPER(b.shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,saleOrderItemCode AS SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID AS SALES_ORDER_ITEM_ID ,AWB ,NULL AS payment_gateway ,payment_mode ,COURIER ,DISPATCH_DATE AS DISPATCH_DATE ,delivered_date AS delivered_date ,CASE WHEN UPPER(FINAL_SHIPPING_STATUS) IN (\'DELIVERED\') THEN 1 END AS DELIVERED_STATUS ,return_flag AS RETURN_FLAG ,CASE WHEN return_flag = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN return_flag = 1 THEN CAST(selling_price AS FLOAT64) END AS returned_sales ,CASE WHEN return_flag = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,CASE WHEN order_status = \'COMPLETE\' THEN date_diff(CAST(delivered_date AS DATE), CAST(order_date AS DATE),day) ELSE date_diff(CURRENT_DATE(), CAST(order_date AS DATE),day) END AS days_in_shipment ,NULL AS ACQUISITION_D ,sku_code ,UPPER(b.product_name_final) AS PRODUCT_NAME_FINAL ,UPPER(b.Product_Category) AS PRODUCT_CATEGORY ,UPPER(b.product_sub_category) AS PRODUCT_SUB_CATEGORY ,b.commonsku ,UPPER(warehouse_name) AS warehouse ,b.pincode ,fa.pincode source_pincode ,cast(null as string) as Source_Name ,cast(null as string) as Mapped_Source_Name ,cast(null as string) as Order_Type FROM tekkitake-wh.maplemonk.tekkitake_unicommerce_fact_items b left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from maplemonk.facility_pincode ) where rw = 1 ) fa on lower(b.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM maplemonk.shipment_status_mapping ) ShipMap WHERE ShipMap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) WHERE NOT (LOWER(b.marketplace) LIKE \'%amazon%\') AND b.reference_code not in (select distinct order_id from maplemonk.tekkitake_flipkart_fact_items) UNION ALL SELECT cast(NULL AS string) customer_id, UPPER(afi.SHOP_NAME) AS Shop_name, \'AMAZON\' AS marketplace, \'AMAZON\' AS CHANNEL, \'AMAZON\' AS SOURCE, afi.ORDER_ID, afi.ORDER_ID AS reference_code, NULL AS PHONE, afi.NAME, COALESCE(UFI.EMAIL, AFI.EMAIL) AS EMAIL, CAST(UFI.shipping_last_update_date AS timestamp) AS SHIPPING_LAST_UPDATE_DATE, afi.SKU, cast(afi.PRODUCT_ID as string) PRODUCT_ID, afi.PRODUCT_NAME, afi.CURRENCY, UPPER(afi.CITY) AS CITY, UPPER(afi.STATE) AS State, UPPER(afi.ORDER_STATUS) AS Order_Status, CAST(afi.ORDER_TIMESTAMP AS DATE) AS Order_Date, CAST(afi.ORDER_TIMESTAMP AS datetime) Order_Time, afi.QUANTITY, IFNULL(TOTAL_SALES, 0) - IFNULL(afi.tax, 0) + IFNULL(DISCOUNT_BEFORE_TAX, 0) AS GROSS_SALES_BEFORE_TAX, DISCOUNT_BEFORE_TAX AS DISCOUNT, afi.TAX, afi.SHIPPING_PRICE, TOTAL_SALES AS SELLING_PRICE, UPPER(UFI.order_status) AS OMS_order_status, UPPER(UFI.shipping_status) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status)) AS FINAL_SHIPPING_STATUS, CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS SALEORDERITEMCODE, CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS SALES_ORDER_ITEM_ID, UFI.awb AS AWB, NULL AS Payment_Gateway, UPPER(UFI.payment_mode) AS Payment_Mode, UPPER( UFI.courier) AS COURIER, UFI.dispatch_date AS DISPATCH_DATE, UFI.delivered_date AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, afi.IS_REFUND AS RETURN_FLAG, CASE WHEN afi.is_refund = 1 THEN CAST(afi.quantity AS INT64) END AS returned_quantity, CASE WHEN afi.is_refund = 1 THEN afi.total_sales END AS returned_sales, CASE WHEN afi.is_refund = 0 AND LOWER(afi.order_status) = \'cancelled\' THEN CAST(afi.quantity AS INT64) END AS cancelled_quantity, NULL AS NEW_CUSTOMER_FLAG, NULL AS ACQUISITION_PRODUCT, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status,UFI.shipping_status)) IN (\'delivered\', \'delivered to origin\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) WHEN LOWER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) END AS Days_in_Shipment, NULL AS ACQUISITION_D, COALESCE(afi.SKU, UFI.PRODUCT_ID) AS SKU_CODE, UPPER(AFI.PRODUCT_NAME_FINAL) AS PRODUCT_NAME_FINAL, UPPER(AFI.PRODUCT_CATEGORY) AS PRODUCT_CATEGORY, UPPER(AFI.PRODUCT_SUB_CATEGORY) AS PRODUCT_SUB_CATEGORY ,AFI.commonsku ,UPPER(UFI.warehouse_name) AS WAREHOUSE ,COALESCE(AFI.pincode, UFI.pincode) AS pincode ,fa.pincode source_pincode ,cast(null as string) as Source_Name ,cast(null as string) as Mapped_Source_Name ,cast(null as string) as Order_Type FROM tekkitake-wh.maplemonk.tekkitake_AMAZON_FACT_ITEMS AFI LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY shipping_last_update_date DESC) AS rw FROM tekkitake-wh.maplemonk.tekkitake_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE \'%amazon%\' ) ufi WHERE ufi.rw = 1 ) UFI ON cast(AFI.order_id as string) = cast(UFI.order_id as string) AND cast(AFI.product_id as string) = cast(UFI.PRODUCT_ID as string) left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from tekkitake-wh.maplemonk.facility_pincode ) where rw = 1 ) fa on lower(ufi.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM tekkitake-wh.maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(UFI.shipping_status, afi.ORDER_STATUS)) = LOWER(ShipMap.shipping_status) UNION ALL SELECT cast(NULL AS string) customer_id, upper(Shop_name) AS Shop_name, \'FLIPKART\' AS marketplace, \'FLIPKART\' AS CHANNEL, \'FLIPKART\' AS SOURCE, fi.ORDER_ID, fi.ORDER_ID AS reference_code, NULL AS PHONE, fi.NAME, COALESCE(UFI.EMAIL, fi.EMAIL) AS EMAIL, CAST(UFI.shipping_last_update_date AS timestamp) AS SHIPPING_LAST_UPDATE_DATE, fi.SKU, cast(fi.PRODUCT_ID as string) PRODUCT_ID, fi.PRODUCT_NAME, cast(null as string) as CURRENCY, UPPER(fi.CITY) AS CITY, UPPER(fi.STATE) AS State, UPPER(fi.order_item_status) AS Order_Status, CAST(fi.ORDER_date AS DATE) AS Order_Date, CAST(fi.ORDER_date AS datetime) Order_Time, fi.QUANTITY, GROSS_SALES_BEFORE_TAX, DISCOUNT_BEFORE_TAX AS DISCOUNT, fi.TAX, fi.SHIPPING_PRICE, line_item_sales AS SELLING_PRICE, UPPER(UFI.order_status) AS OMS_order_status, UPPER(UFI.shipping_status) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status)) AS FINAL_SHIPPING_STATUS, line_item_id AS SALEORDERITEMCODE, line_item_id AS SALES_ORDER_ITEM_ID, UFI.awb AS AWB, NULL AS Payment_Gateway, UPPER(UFI.payment_mode) AS Payment_Mode, UPPER( UFI.courier) AS COURIER, UFI.dispatch_date AS DISPATCH_DATE, UFI.delivered_date AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, fi.IS_REFUND AS RETURN_FLAG, CASE WHEN fi.is_refund = 1 THEN CAST(fi.quantity AS INT64) END AS returned_quantity, CASE WHEN fi.is_refund = 1 THEN fi.total_sales END AS returned_sales, CASE WHEN fi.is_refund = 0 AND LOWER(fi.order_item_status) = \'cancelled\' THEN CAST(fi.quantity AS INT64) END AS cancelled_quantity, NULL AS NEW_CUSTOMER_FLAG, NULL AS ACQUISITION_PRODUCT, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status,UFI.shipping_status)) IN (\'delivered\', \'delivered to origin\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(fi.ORDER_date AS DATE), DAY) WHEN LOWER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(fi.ORDER_date AS DATE), DAY) END AS Days_in_Shipment, NULL AS ACQUISITION_D, COALESCE(fi.SKU, UFI.PRODUCT_ID) AS SKU_CODE, UPPER(fi.PRODUCT_NAME) AS PRODUCT_NAME_FINAL, UPPER(fi.CATEGORY) AS PRODUCT_CATEGORY, cast(null as string) AS PRODUCT_SUB_CATEGORY, fi.sku as commonsku, UPPER(UFI.warehouse_name) AS WAREHOUSE, COALESCE(fi.pincode, UFI.pincode) AS pincode, fa.pincode source_pincode, cast(null as string) as Source_Name, cast(null as string) as Mapped_Source_Name, cast(null as string) as Order_Type FROM tekkitake-wh.maplemonk.tekkitake_flipkart_fact_items fi LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY shipping_last_update_date DESC) AS rw FROM tekkitake-wh.maplemonk.tekkitake_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE \'%flipkart%\' ) ufi WHERE ufi.rw = 1 ) UFI ON cast(fi.order_id as string) = cast(UFI.order_id as string) AND cast(fi.product_id as string) = cast(UFI.PRODUCT_ID as string) left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from tekkitake-wh.maplemonk.facility_pincode ) where rw = 1 ) fa on lower(ufi.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM tekkitake-wh.maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(UFI.shipping_status, fi.ORDER_item_STATUS)) = LOWER(ShipMap.shipping_status) ; CREATE OR REPLACE TABLE tekkitake-wh.maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM tekkitake-wh.maplemonk.tekkitake_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM tekkitake-wh.maplemonk.tekkitake_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE tekkitake-wh.maplemonk.tekkitake_sales_consolidated AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM tekkitake-wh.maplemonk.tekkitake_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM tekkitake-wh.maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM tekkitake-wh.maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email; ALTER TABLE tekkitake-wh.maplemonk.tekkitake_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE tekkitake-wh.maplemonk.tekkitake_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE tekkitake-wh.maplemonk.tekkitake_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM tekkitake-wh.maplemonk.tekkitake_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE tekkitake-wh.maplemonk.tekkitake_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE tekkitake-wh.maplemonk.tekkitake_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM tekkitake-wh.maplemonk.tekkitake_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE tekkitake-wh.maplemonk.tekkitake_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM tekkitake-wh.maplemonk.tekkitake_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE tekkitake-wh.maplemonk.tekkitake_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE tekkitake-wh.maplemonk.tekkitake_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM tekkitake-wh.maplemonk.tekkitake_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE tekkitake-wh.maplemonk.tekkitake_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
